<script setup lang="ts">import Table from './common/Table.vue';import Status from './common/Status.vue';import {fmt} from '../utils/format';
const p=defineProps<{runs:any[];user?:any}>(),emit=defineEmits(['open','requeue']);
function tag(r:any){if(r.batch?.missing_snapshot)return '缺原始资料';if(r.batch?.current_matches_queued===false)return '排队后已改票·按原批';if(r.batch?.has_snapshot)return '批次已冻结';return ''}
function tagClass(r:any){if(r.batch?.missing_snapshot)return 'tag-missing';if(r.batch?.current_matches_queued===false)return 'tag-drifted';return 'tag-frozen'}
function canRequeue(r:any){return p.user&&p.user.role!=='viewer'&&(r.status==='running'||r.status==='queued')}
</script><template><Table :headers="['研究运行','状态','资料批次','重复/seed','κ','打开']"><tr v-for="r in runs" :key="r.id"><td><strong>{{r.name}}</strong><small>#{{r.id}} / 研究{{r.study_id}}</small></td><td><Status :value="r.status"/><small v-if="r.error" class="error-text">{{r.error}}</small></td><td><small :class="['batch-tag',tagClass(r)]">{{tag(r)}}</small><button v-if="canRequeue(r)" class="link-button" @click="emit('requeue',r)">中断恢复 ↻</button></td><td>{{r.config.bootstrap_repeats}} / {{r.config.seed}}</td><td>{{r.kappa===null?'—':fmt(r.kappa,6)}}</td><td><button @click="$emit('open',r)">查看评议 ↗</button></td></tr></Table></template>
